@startuml
class InventoryItem {
  +id: String
  +name: String
  +quantity: Integer
  +unitPrice: Number
  +active: Boolean
  +stockDate: Date
}
class InventoryItemService {
  +list(): InventoryItem
  +create(name: String, quantity: Integer, unitPrice: Number, active: Boolean, stockDate: Date): InventoryItem
  +update(id: String): InventoryItem
  +remove(id: String): void
}
class InventoryItemRepository {
  +list(): InventoryItem
  +findById(id: String): InventoryItem
  +create(value: InventoryItem): InventoryItem
  +update(id: String): InventoryItem
  +remove(id: String): void
}
InventoryItemService --> InventoryItemRepository : uses
InventoryItemRepository --> InventoryItem : persists
@enduml
